import java.util.Scanner;

public class Main {
    static int n, m, P;
    static int[][] dwu;
    static long[] dp1;
    static long[][] dp2, dp3;
    static long[] ile;

    static void mulself(long[] a, int b) {
        for (int i = 0; i < a.length; i++) {
            a[i] = (a[i] * b) % P;
        }
    }

    static long mul(int a, int b) {
        return ((long) a * b) % P;
    }

    static void add(long[] a, long b) {
        for (int i = 0; i < a.length; i++) {
            a[i] = (a[i] + b) % P;
        }
    }

    static void add(long[] a, long b, int index) {
        a[index] = (a[index] + b) % P;
    }

    static void add(long[] a, long b) {
        for (int i = 0; i < a.length; i++) {
            a[i] = (a[i] + b) % P;
        }
    }

    static void add(long[] a, long b, int index) {
        a[index] = (a[index] + b) % P;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        P = sc.nextInt();

        int MAX = 511;
        dwu = new int[MAX][MAX];
        dp1 = new long[MAX];
        dp2 = new long[MAX][MAX];
        dp3 = new long[MAX][MAX];
        ile = new long[MAX];

        for (int i = 0; i <= n + 1; i++) {
            for (int j = 0; j <= i; j++) {
                if (j == 0) {
                    dwu[i][j] = 1;
                } else {
                    dwu[i][j] = dwu[i - 1][j];
                    dwu[i][j] = (dwu[i][j] + dwu[i - 1][j - 1]) % P;
                }
            }
        }

        for (int i = 0; i <= m + 1; i++) {
            dp1[i] = 0;
            ile[i] = 0;
        }
        ile[0] = 1;

        for (int i = 1; i <= m; i++) {
            for (int j = 0; j < i; j++) {
                long pom = 0;
                pom = (pom + mul((int) dp1[j], ile[i - j - 1])) % P;
                pom = (pom + mul((int) dp1[i - j - 1], ile[j])) % P;
                long temp = j + 1;
                pom = (pom * temp) % P;
                long half = (long) j * (j + 1) / 2;
                long term = (mul((int) ile[i - j - 1], ile[j]) * half) % P;
                pom = (pom + term) % P;
                mulself(new long[]{pom}, dwu[i - 1][j]);
                add(dp1, pom);
                long pom2 = dwu[i - 1][j];
                pom2 = (pom2 * ile[j]) % P;
                pom2 = (pom2 * ile[i - j - 1]) % P;
                pom2 = (pom2 * (j + 1)) % P;
                ile[i] = (ile[i] + pom2) % P;
            }
            ile[i] = (ile[i] + ile[i]) % P;
            dp1[i] = (dp1[i] + dp1[i]) % P;
        }

        for (int i = 0; i <= n + 1; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; k <= m; k++) {
                    if (j + k <= m && i + k + 1 <= n + 1) {
                        long pom = dp2[i][j];
                        pom = (pom * dwu[m - j][k]) % P;
                        pom = (pom * ile[k]) % P;
                        long pom3 = dp3[i][j];
                        pom3 = (pom3 * ile[k]) % P;
                        long temp1 = (long) dp1[k] % P;
                        pom3 = (pom3 + (temp1 * dp2[i][j]) % P) % P;
                        pom3 = (pom3 * dwu[m - j][k]) % P;
                        dp2[i + k + 1][j + k] = (dp2[i + k + 1][j + k] + pom) % P;
                        dp3[i + k + 1][j + k] = (dp3[i + k + 1][j + k] + pom3) % P;
                    }
                }
            }
        }

        System.out.println(dp3[n + 1][m]);
        sc.close();
    }
}

